--//=================================================================
--// IMAGEM DE FUNDO EMBUTIDA (gerada automaticamente - nao edite)
--//=================================================================
local IMAGE_B64 = [==[]==]

-- Decodificador base64 em Lua puro (nao depende de crypt do executor)
local B64CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64TABLE = {}
for i = 1, #B64CHARS do B64TABLE[B64CHARS:sub(i, i)] = i - 1 end

local function base64decode(data)
    data = data:gsub("[^" .. B64CHARS .. "=]", "")
    return (data:gsub(".", function(x)
        if x == "=" then return "" end
        local r, f = "", B64TABLE[x]
        for i = 6, 1, -1 do
            r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
        end
        return r
    end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
        if #x ~= 8 then return "" end
        local c = 0
        for i = 1, 8 do c = c + (x:sub(i, i) == "1" and 2 ^ (8 - i) or 0) end
        return string.char(c)
    end))
end

----------------------------------------------------------------
--// CARREGA A IMAGEM EMBUTIDA (writefile + getcustomasset)
----------------------------------------------------------------
local function resolveBackgroundImage()
    if CONFIG.BackgroundImage ~= "rbxassetid://0" then
        return CONFIG.BackgroundImage
    end
    if typeof(writefile) == "function" and typeof(getcustomasset) == "function" then
        local ok, result = pcall(function()
            writefile("miku_maintenance_bg.jpg", base64decode(IMAGE_B64))
            return getcustomasset("miku_maintenance_bg.jpg")
        end)
        if ok and result then
            return result
        end
        warn("[MikuMaintenance] Falha ao carregar imagem embutida: " .. tostring(result))
    else
        warn("[MikuMaintenance] getcustomasset/writefile indisponiveis. Cole um ID em CONFIG.BackgroundImage.")
    end
    return nil
end

