--// INDICADOR CIRCULAR PLANO 2D (círculo + traços orbitais)
----------------------------------------------------------------
local indicatorHolder = Create("Frame", {
    Name = "Indicator",
    LayoutOrder = 2,
    Size = UDim2.fromOffset(60, 60),
    BackgroundTransparency = 1,
    ZIndex = 5,
}, row)

local dotStroke -- referência para o refresh de espessura

local function buildIndicator(holder)
    local rng = Random.new()

    -- anel fino PLANO (aparência 2D, sem volume)
    local flatRing = Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromScale(0.86, 0.86),
        BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5,
    }, holder)
    Create("UICorner", { CornerRadius = UDim.new(1, 0) }, flatRing)
    Create("UIStroke", {
        Color = CONFIG.AccentColor, Thickness = 2,
        Transparency = 0.82, ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    }, flatRing)

    -- círculo central plano
    local dot = Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromScale(0.16, 0.16),
        BackgroundColor3 = CONFIG.AccentColor,
        BackgroundTransparency = 0.05, BorderSizePixel = 0, ZIndex = 6,
    }, holder)
    Create("UICorner", { CornerRadius = UDim.new(1, 0) }, dot)
    dotStroke = Create("UIStroke", {
        Color = Color3.fromRGB(175, 222, 255),
        Transparency = 0.55,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    }, dot)

    -- anéis de traços orbitais (planos, girando no próprio plano)
    local rings = {
        { count = 12, radius = 0.42, minLen = 0.06, maxLen = 0.14, thick = 0.034, speed = 110, dir =  1, minT = 0.32, maxT = 0.55 },
        { count = 9,  radius = 0.33, minLen = 0.05, maxLen = 0.11, thick = 0.030, speed =  70, dir = -1, minT = 0.38, maxT = 0.60 },
        { count = 6,  radius = 0.25, minLen = 0.04, maxLen = 0.08, thick = 0.026, speed =  45, dir =  1, minT = 0.44, maxT = 0.65 },
    }

    for _, cfg in ipairs(rings) do
        local ringFrame = Create("Frame", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1, ZIndex = 5,
        }, holder)

        for i = 1, cfg.count do
            local angle = ((i - 1) / cfg.count) * math.pi * 2 + rng:NextNumber(-0.06, 0.06)
            local len   = rng:NextNumber(cfg.minLen, cfg.maxLen)
            local baseT = rng:NextNumber(cfg.minT, cfg.maxT)

            local tick = Create("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.new(cfg.thick, 0, len, 0),
                Position = UDim2.new(0.5 + math.cos(angle) * cfg.radius, 0, 0.5 + math.sin(angle) * cfg.radius, 0),
                Rotation = math.deg(angle) + 90,
                BackgroundColor3 = CONFIG.AccentColor,
                BackgroundTransparency = baseT,
                BorderSizePixel = 0, ZIndex = 5,
            }, ringFrame)
            Create("UICorner", { CornerRadius = UDim.new(1, 0) }, tick)

            -- variação suave de opacidade durante a rotação
            TweenService:Create(tick, TweenInfo.new(
                rng:NextNumber(0.9, 1.7), Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true
            ), { BackgroundTransparency = math.min(baseT + 0.25, 0.92) }):Play()
        end

        -- rotação contínua e perfeitamente suave no plano 2D
        TweenService:Create(ringFrame, TweenInfo.new(
            360 / math.abs(cfg.speed), Enum.EasingStyle.Linear
        ), { Rotation = 360 * cfg.dir }):Play()
    end
end
buildIndicator(indicatorHolder)

----------------------------------------------------------------
--// SISTEMA DE TROCA DE MENSAGENS (loop infinito)
----------------------------------------------------------------
local msgIndex = 1
local function startMessages()
    task.spawn(function()
        task.wait(1.1)
        while screenGui.Parent do
            messageLabel.Text = STATUS_MESSAGES[msgIndex]
            messageLabel.Position = UDim2.fromOffset(0, 10)
            Tween(messageLabel, 0.5, { TextTransparency = 0.05, Position = UDim2.fromOffset(0, 0) })
            task.wait(2.6)
            Tween(messageLabel, 0.4, { TextTransparency = 1, Position = UDim2.fromOffset(0, -10) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
            task.wait(0.45)
            msgIndex = (msgIndex % #STATUS_MESSAGES) + 1
        end
    end)
end

