local function makeModalButton(text, filled)
    local btn = Create("TextButton", {
        Size = UDim2.new(0.5, -6, 1, 0),
        BackgroundColor3 = filled and CONFIG.AccentColor or Color3.fromRGB(30, 42, 60),
        BackgroundTransparency = filled and 0.12 or 0.15,
        Text = text,
        Font = Enum.Font.GothamSemibold,
        TextColor3 = filled and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(205, 218, 238),
        TextScaled = true,
        BorderSizePixel = 0, ZIndex = 23,
    }, btnRow)
    Create("UICorner", { CornerRadius = UDim.new(0, 10) }, btn)
    if filled then
        Create("UIGradient", {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(105, 196, 255)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(52, 132, 232)),
            }),
            Rotation = 90,
        }, btn)
    end

    local scale = Create("UIScale", {}, btn)
    btn.MouseEnter:Connect(function()
        Tween(btn, 0.15, { BackgroundTransparency = filled and 0.0 or 0.05 })
        Tween(scale, 0.15, { Scale = 1.05 })
    end)
    btn.MouseLeave:Connect(function()
        Tween(btn, 0.15, { BackgroundTransparency = filled and 0.12 or 0.15 })
        Tween(scale, 0.15, { Scale = 1 })
    end)
    btn.MouseButton1Down:Connect(function() Tween(scale, 0.1, { Scale = 0.92 }) end)
    btn.MouseButton1Up:Connect(function() Tween(scale, 0.1, { Scale = 1.05 }) end)
    return btn
end

local yesBtn = makeModalButton("Yes", true)
local noBtn  = makeModalButton("No", false)

----------------------------------------------------------------
--// ABRIR / FECHAR MODAL
----------------------------------------------------------------
local modalOpen = false

local function openModal()
    if modalOpen then return end
    modalOpen = true
    modalRoot.Visible = true
    if blur then blur.Enabled = true end
    cardScale.Scale = 0.92
    if blur then Tween(blur, 0.45, { Size = 24 }) end
    Tween(modalRoot, 0.35, { BackgroundTransparency = 0.38 })
    Tween(cardScale, 0.5, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
end

local function closeModal()
    if not modalOpen then return end
    modalOpen = false
    if blur then Tween(blur, 0.25, { Size = 0 }) end
    Tween(modalRoot, 0.22, { BackgroundTransparency = 1 })
    Tween(cardScale, 0.22, { Scale = 0.94 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
    task.delay(0.24, function()
        if not modalOpen then
            modalRoot.Visible = false
            if blur then blur.Enabled = false end
        end
    end)
end

