--// RESPONSIVIDADE (ViewportSize - celular landscape, tablet, PC)
----------------------------------------------------------------
local function refreshLayout()
    local cam = workspace.CurrentCamera
    if not cam then return end
    local vp = cam.ViewportSize
    local unit = math.min(vp.X, vp.Y)

    content.Position = UDim2.new(0, unit * 0.05, 0.93, 0)
    title.Size = UDim2.new(1, 0, 0, unit * 0.075)
    row.Size = UDim2.new(1, 0, 0, unit * 0.17)
    contentList.Padding = UDim.new(0, unit * 0.025)
    rowList.Padding = UDim.new(0, unit * 0.035)
    messageWrap.Size = UDim2.new(0.62, 0, 0, unit * 0.05)

    indicatorHolder.Size = UDim2.fromOffset(unit * 0.17, unit * 0.17)
    if dotStroke then dotStroke.Thickness = math.max(1, unit * 0.004) end

    xHolder.Position = UDim2.new(1, -unit * 0.035, 0, unit * 0.035)
    xHolder.Size = UDim2.fromOffset(unit * 0.11, unit * 0.11)
    xStroke.Thickness = math.max(1, unit * 0.0022)

    card.Size = UDim2.fromOffset(math.min(vp.X * 0.5, unit * 0.85), unit * 0.30)
    cardCorner.CornerRadius = UDim.new(0, unit * 0.028)
    cardList.Padding = UDim.new(0, unit * 0.022)
end

workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
    local cam = workspace.CurrentCamera
    if cam then
        cam:GetPropertyChangedSignal("ViewportSize"):Connect(refreshLayout)
    end
    refreshLayout()
end)
if workspace.CurrentCamera then
    workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(refreshLayout)
end
refreshLayout()

